/**
 * @summary Get a download URL for a stored file (self-hosted only)
 */
export type getStorageDownloadUrlResponse200 = {
  data: GetStorageDownloadUrl200
  status: 200
}
    
export type getStorageDownloadUrlResponseSuccess = (getStorageDownloadUrlResponse200) & {
  headers: Headers;
};
;

export type getStorageDownloadUrlResponse = (getStorageDownloadUrlResponseSuccess)

export const getGetStorageDownloadUrlUrl = (params: GetStorageDownloadUrlParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/storage/download-url?${stringifiedParams}` : `/storage/download-url`
}

export const getStorageDownloadUrl = async (params: GetStorageDownloadUrlParams, options?: RequestInit): Promise<getStorageDownloadUrlResponse> => {
  
  return coployFetch<getStorageDownloadUrlResponse>(getGetStorageDownloadUrlUrl(params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}



